<div class="page-header"><div><p class="eyebrow">ACADEMIC POLICY</p><h1>Grade configuration</h1><p>Configure assessment weighting and a transparent grading scale.</p></div></div>
<div class="dashboard-panels"><section class="panel"><h2>Grading scale</h2><p class="form-hint">Example scales must be reviewed and approved by the institution before use. Existing offerings retain their assigned scale.</p><form action="/grades/setup" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="scheme"><label class="form-label">Example scale<select class="form-select" name="scale"><option value="5">University 5-point example</option><option value="4">University 4-point example</option></select></label><button class="btn btn-primary mt-3">Activate example scale</button></form><div class="mt-3"><strong>Available schemes</strong><?php foreach($schemes as $s):?><div class="info-row"><?= e($s['name']) ?> · <?= e($s['status']) ?></div><?php endforeach; ?></div></section>
<section class="panel"><h2>Assessment components</h2><p class="form-hint">Create one continuous assessment and one examination component per offering; their maximums must total 100.</p><form method="post" action="/grades/setup"><?= csrf_field() ?><input type="hidden" name="action" value="components"><div class="form-grid"><label class="form-label">Course<select class="form-select" name="course_id"><?php foreach($courses as $c):?><option value="<?= (int)$c['id'] ?>"><?= e($c['code']) ?></option><?php endforeach; ?></select></label><label class="form-label">Semester<select class="form-select" name="semester_id"><?php foreach($semesters as $s):?><option value="<?= (int)$s['id'] ?>"><?= e($s['session_name'].' · '.$s['semester_number']) ?></option><?php endforeach; ?></select></label><label class="form-label">CA maximum<input class="form-control" type="number" name="ca_max" min="1" max="99" step="0.01" value="40" required></label><label class="form-label">Exam maximum<input class="form-control" type="number" name="exam_max" min="1" max="99" step="0.01" value="60" required></label></div><button class="btn btn-primary mt-3">Configure components</button></form></section></div>
<section class="panel"><h2>Repeat-course and prerequisite rules</h2><form method="post" action="/grades/setup"><?= csrf_field() ?><input type="hidden" name="action" value="policy"><div class="form-grid"><label class="form-label">Repeat-course policy<select class="form-select" name="repeat_policy"><option value="">Not configured (CGPA hidden if repeat exists)</option><?php foreach(['all_attempts'=>'Count all attempts','latest_published'=>'Keep latest published attempt','highest_published'=>'Keep highest published attempt'] as $val=>$lab):?><option value="<?= e($val) ?>" <?= ($policy['repeat_policy']??'')===$val?'selected':'' ?>><?= e($lab) ?></option><?php endforeach; ?></select></label><label class="form-label">Minimum prerequisite grade point (optional)<input class="form-control" type="number" min="0" max="5" step="0.01" name="pass_threshold" value="<?= e($policy['prerequisite_min_grade_point']??'') ?>"></label></div><button class="btn btn-outline-primary mt-3">Save academic policy</button></form></section>
